      "id": "modern-c05-l24-p02-033",
      "title": "ジエムの暗殺と相次ぐクーデタ",
      "body": [
        "もはや政権が維持できないと思ったアメリカは、クーデタで<strong class=\"source-bold\">ゴ＝ディン＝ジエムを暗殺</strong>させた（<strong class=\"source-bold\">南ベトナム＝クーデタ</strong>）。しかし、これ以後<strong class=\"source-bold\">ベトナム共和国は一気に弱体化</strong>し、約1年半の間で13回もクーデタが起こる異常事態！。"
      ],
      "plainBody": [
        "もはや政権が維持できないと思ったアメリカは、クーデタでゴ＝ディン＝ジエムを暗殺させた（南ベトナム＝クーデタ）。しかし、これ以後ベトナム共和国は一気に弱体化し、約1年半の間で13回もクーデタが起こる異常事態！。"
      ],
