      "body": [
        "そして、アメリカの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョンソン</strong></span>大統領は議会に対し「<strong class=\"source-bold\">ベトナム攻撃への白紙委任</strong>を与えてほしい」と要請し、議会もほぼ全会一致でこれを認めた。"
      ],
