      "title": "枯れ葉作戦と環境破壊",
      "body": [
        "行き詰まったアメリカは、解放勢力の拠点を<ruby>潰<rt>つぶ</rt></ruby>すために<strong class=\"source-bold\">森林にダイオキシン類を含む有害な農薬を<ruby>撒<rt>ま</rt></ruby>く「<ruby>枯<rt>か</rt></ruby>れ<ruby>葉<rt>は</rt></ruby>作戦」</strong>など、人道に反するような攻撃もおこなったんだ。「枯れ葉剤」による深刻な環境破壊で、ベトナムでは現在でも<ruby>胎児<rt>たいじ</rt></ruby>の奇形などが問題になっている。"
      ],
      "plainBody": [
        "行き詰まったアメリカは、解放勢力の拠点を潰すために森林にダイオキシン類を含む有害な農薬を撒く「枯れ葉作戦」など、人道に反するような攻撃もおこなったんだ。「枯れ葉剤」による深刻な環境破壊で、ベトナムでは現在でも胎児の奇形などが問題になっている。"
      ],
