      "title": "グエン＝ヴァン＝リンの判断",
      "body": [
        "こうしたなかで最高指導者となったグエン＝ヴァン＝リンは、「ソ連はペレストロイカを始めたし、中国は改革・開放で成果を上げている。停滞を打破するためには、<strong class=\"source-bold\">ベトナムも<ruby>市場<rt>しじょう</rt></ruby>経済を導入</strong>しよう！」と考えて、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイモイ</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>刷新<rt>さっしん</rt></ruby></strong></span>】</strong>を開始した。"
      ],
      "plainBody": [
        "こうしたなかで最高指導者となったグエン＝ヴァン＝リンは、「ソ連はペレストロイカを始めたし、中国は改革・開放で成果を上げている。停滞を打破するためには、ベトナムも市場経済を導入しよう！」と考えて、ドイモイ 【刷新】を開始した。"
      ],
