      "id": "modern-c05-l24-p03-005",
      "title": "国づくりと三つの団体",
      "body": [
        "スカルノの国づくりで一番の問題は、これまでの民族運動で形成された複数の団体をどうやってまとめるか、ということだ。<strong class=\"source-bold\">エリートを中心</strong>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア国民党</strong></span>、<strong class=\"source-bold\">ムスリム商人を中心</strong>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サレカット＝イスラム</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イスラーム同盟</strong></span>】</strong>、そして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア共産党</strong></span>。"
      ],
      "plainBody": [
        "スカルノの国づくりで一番の問題は、これまでの民族運動で形成された複数の団体をどうやってまとめるか、ということだ。エリートを中心とするインドネシア国民党、ムスリム商人を中心とするサレカット＝イスラム 【イスラーム同盟】、そしてインドネシア共産党。"
      ],
