      "title": "九・三〇事件とスハルトの掌握",
      "body": [
        "1965年、アメリカがベトナムに本格<ruby>介入<rt>かいにゅう</rt></ruby>すると、<strong class=\"source-bold\">右派軍人によるクーデタ</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>九<rt>く</rt></ruby>・<ruby>三〇<rt>さんじゅう</rt></ruby>事件</strong></span>）によって<strong class=\"source-bold\">共産党が<ruby>潰<rt>つぶ</rt></ruby>され</strong>、<strong class=\"source-bold\">スカルノが失脚</strong>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スハルト</strong></span>が権力を掌握した。"
      ],
      "plainBody": [
        "1965年、アメリカがベトナムに本格介入すると、右派軍人によるクーデタ（九・三〇事件）によって共産党が潰され、スカルノが失脚してスハルトが権力を掌握した。"
      ],
