      "id": "modern-c05-l24-p03-078",
      "title": "フィリピンとインドネシアの政権",
      "body": [
        "まずフィリピンでは親米の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルコス</strong></span>政権が成立して対米従属路線をとり、インドネシアでも<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>九<rt>く</rt></ruby>・<ruby>三〇<rt>さんじゅう</rt></ruby>事件</strong></span>が起きて「<strong class=\"source-bold\">反米・<ruby>容<rt>よう</rt></ruby><ruby>共<rt>きょう</rt></ruby></strong>」の<strong class=\"source-bold\">スカルノが失脚</strong>し、「<strong class=\"source-bold\">親米・反共</strong>」の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スハルト</strong></span>政権ができた。"
      ],
