export const sourcePages = {
  "436": "<h2>436</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第24回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">戦後の</strong>インド・東南アジア</span></h1>\n<p>前回に引き続いてアジアの戦後史だ。今回は、インドと東南アジア、特にベトナム戦争が重要テーマだ！</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">大きくつかもう！</span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span></td></tr><tr><td><strong class=\"source-bold\">戦後のインドと第三世界の形成</strong></td><td><strong class=\"source-bold\">インドシナ戦争とベトナム戦争</strong></td><td><strong class=\"source-bold\">戦後の東南アジア</strong></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">437〜440ページ</span></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">441〜447ページ</span></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">447〜453ページ</span></td></tr></tbody></table></div>\n<blockquote><p>ベトナム戦争は、アメリカ国内、東南アジア、さらに国際関係にも大きく影響するよ！</p></blockquote>\n<p>イギリスの植民地だったインドは、独立する時に<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ヒンドゥー教徒のインド</u>と<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">イスラーム教徒のパキスタン</u>に分離・独立した。ガンディーは「分離独立したら、ずっと対立が続いて大変なことになる！」って言ってたけど、本当にそのとおりになっちゃうよ。それから、独立後のインドは「非同盟主義」を唱えて「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第三世界</u>」の中心になるよ。今回は、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アジア・アフリカ会議</u>の話もするからね。そして、戦後史に大きな影響を与えるのが<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ベトナム戦争</u>だ。アメリカ国内、ベトナム国内だけじゃなく、米ソ関係、中ソ関係、東南アジアの周辺国の政局……さまざまなところに影響するからね！ これまでのところも思い出しながら、世界全体をつなげていこう。</p>\n<p>それじゃあ、戦後のインドと東南アジア、いってみよう〜。</p>",
  "437": "<h2>437</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後のインドと第三世界の形成</u></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">戦後のインドと第三世界の形成</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ インドとパキスタンの分離独立で、ヒンドゥーとイスラームの対立が激化！</strong></span></h4>\n<p>第二次世界大戦で<ruby>疲弊<rt>ひへい</rt></ruby>したイギリスはインド支配を<ruby>諦<rt>あきら</rt></ruby>め、1947年、<strong class=\"source-bold\">労働党のアトリー</strong>が<strong class=\"source-bold\">インド独立法</strong>を成立させた。インドは、<strong class=\"source-bold\">ヒンドゥー教徒を中心</strong>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド連邦</strong></span>と<strong class=\"source-bold\">イスラーム教徒を中心</strong>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パキスタン</strong></span>に分かれ、イギリス連邦内の自治領として独立したよ。インド首相は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民会議派</strong></span>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネルー</strong></span>、パキスタン<ruby>総督<rt>そうとく</rt></ruby>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全インド＝ムスリム連盟</strong></span>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジンナー</strong></span>だ。ただ、この分離独立が深刻な対立を引き起こしたんだ。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">パキスタン</strong></td><td><strong class=\"source-bold\">インド</strong></td></tr><tr><td><strong class=\"source-bold\">バングラデシュ</strong></td><td>（1971独立）</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">カシミール帰属問題</span></td><td><span data-source-color=\"red\" data-source-marker=\"battle\" style=\"color:#e52715\">⚔</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">中印国境紛争</span></td><td><span data-source-color=\"red\" data-source-marker=\"battle\" style=\"color:#e52715\">⚔</span></td></tr></tbody></table></div>\n<p>イギリス領インド帝国は、<strong class=\"source-bold\">イギリスの</strong><ruby>直轄地<rt>ちょっかつち</rt></ruby>に加えて約550の<ruby>藩王国<rt>はんおうこく</rt></ruby>があったよね。直轄地は「<strong class=\"source-bold\">ヒンドゥー教徒が多い地域</strong>」と「<strong class=\"source-bold\">イスラーム教徒が多い地域</strong>」で分かれたんだけど、問題は「<strong class=\"source-bold\">それぞれの地域の少数派</strong>」と「<strong class=\"source-bold\">藩王国</strong>」……。独立直後からパキスタンからヒンドゥー教徒が、インドからイスラーム教徒が難民として大移動を始め、この移動の途中での虐殺や略奪が起こった。さらに「藩王国」の問題はもっとヤバい！ 藩王は自分の宗教で<ruby>帰属<rt>きぞく</rt></ruby>を決めたんだけど、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カシミール地方</strong></span>は<strong class=\"source-bold\">藩王がヒンドゥー教徒</strong>なのに、<strong class=\"source-bold\">住民はイスラーム教徒が多かった</strong>から、藩王が「<strong class=\"source-bold\">インドに帰属</strong>する」って発表すると、イスラーム系住民の暴動が発生！ そこにインド、パキスタン両国が出兵して<strong class=\"source-bold\">第1次印パ戦争</strong> <strong class=\"source-bold\">【インド＝パキスタン戦争】</strong>が起きちゃった。ここから始まる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カシミール帰属問題</strong></span>は、現在まで未解決だよ。</p>\n<p>こうしたヒンドゥー教徒とイスラーム教徒の対立のなかで、<strong class=\"source-bold\"><ruby>融和<rt>ゆうわ</rt></ruby>を説き続けた</strong>のが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガンディー</strong></span>だ。しかし、イスラームとの融和を解くガンディーは、狂信的なヒンドゥー教徒によって<strong class=\"source-bold\">暗殺されてしまった</strong>んだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 独立後のインドはイギリスとは距離を置き、第三世界の中心に！</strong></span></h4>\n<p>独立後のインドは、ウェストミンスター<ruby>憲章<rt>けんしょう</rt></ruby>にある「<ruby>王冠<rt>おうかん</rt></ruby>への忠誠」を拒否して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド共和国</strong></span>になった。そしたらイギリスは「じゃあ忠誠を誓わなくてもいいから、イギリス連邦に残って！」と言ってきた。だから<strong class=\"source-bold\">インドは今でもイギリス連邦の一員</strong>だよ。そして、初代首相の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネルー</strong></span>は新憲法で<strong class=\"source-bold\">政教分離</strong>を規定して、とにかく政治から宗教色を消した。さらに、<strong class=\"source-bold\">カーストによる身分差別・<ruby>不可触民制<rt>ふかしょくみんせい</rt></ruby>も禁止</strong>したんだけど、現実に差別をなくすのはなかなか難しいよね。</p>\n<p>経済的には、土地改革と工業化を目指す<strong class=\"source-bold\">社会主義的な五カ年計画</strong>を進めたんだけど、重工業に<ruby>偏<rt>かたよ</rt></ruby>りすぎて伝統的な<ruby>木綿<rt>もめん</rt></ruby>工業や農業はかえって停滞した。植民地経済</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "438": "<h2>438</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第24回</strong></span> 戦後のインド・東南アジア</p></blockquote>\n<p>から抜け出すのは難しいね。そうはいっても、政治的には<strong class=\"source-bold\">国民会議派が議会で圧倒的多数</strong>となり、しばらくは「一党優位体制」が続くよ。ただちゃんと選挙はやってるから、ソ連とかの一党<ruby>独裁<rt>どくさい</rt></ruby>とは違うからね。</p>\n<p>一方で、ネルーは<strong class=\"source-bold\">米ソどちらの陣営とも同盟しない非同盟・中立外交</strong>を進め、1954年の中国の<ruby>周恩来<rt>しゅうおんらい</rt></ruby>首相との会談（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネルー・周恩来会談</strong></span>）での「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和五原則</strong></span>」が、翌年の<strong class=\"source-bold\">アジア・アフリカ会議の基本原則</strong>になった。アジア・アフリカ会議については、このあとすぐに説明するから、いったん飛ばすよ。</p>\n<p>ただ、インドは周辺国との激しい対立を抱えている。まず、<strong class=\"source-bold\">カシミール問題</strong>でパキスタンとはたびたび戦闘が起こり（<strong class=\"source-bold\">印パ戦争</strong>）、中国とも<strong class=\"source-bold\">チベットをめぐる対立</strong>が始まった。これは、1914年にイギリスとチベット、中華民国の間で定めた国境（<strong class=\"source-bold\">マクマホン＝ライン</strong>）を中国（中華人民共和国）が認めず、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダライ＝ラマ14世</strong></span>が<strong class=\"source-bold\">インドに<ruby>亡命<rt>ぼうめい</rt></ruby></strong>したから、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中印国境紛争</strong></span>に発展した。そしてインドは、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ対立</strong></span>を背景にソ連に接近、「敵が一緒だと愛が芽生える」パターンだね。一方の中国は、インドを<ruby>牽制<rt>けんせい</rt></ruby>するためにパキスタンに接近、「<strong class=\"source-bold\">ソ連・インド</strong>」と「<strong class=\"source-bold\">中国・パキスタン</strong>」という組合せができちゃったんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 新興独立国が結集！ アジア・アフリカ会議の開催で、第三世界が形成された！</strong></span></h4>\n<p>1954年、ネルーを中心に<strong class=\"source-bold\">南アジア・東南アジア</strong>の各国首脳（インド・パキスタン・ビルマ・セイロン・インドネシア）が<strong class=\"source-bold\">コロンボ会議</strong>を開き、インドシナ戦争の終結や中国の国連加盟などを宣言するとともに、<strong class=\"source-bold\">アジア＝アフリカ会議の開催を決定</strong>した。さらに同年、インドと中国のチベット協定<ruby>締結<rt>ていけつ</rt></ruby>をきっかけに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネルー・周恩来会談</strong></span>が開かれ、「<strong class=\"source-bold\">領土保全と主権の尊重、相互<ruby>不侵略<rt>ふしんりゃく</rt></ruby>、内政<ruby>不干渉<rt>ふかんしょう</rt></ruby>、平等と<ruby>互恵<rt>ごけい</rt></ruby>、平和的共存</strong>」からなる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和五原則</strong></span>がまとめられ、これが<strong class=\"source-bold\">アジア・アフリカ会議の基本原則</strong>になった。</p>\n<blockquote><p>ナセルやスカルノは、アジア・アフリカ会議のあと、「非同盟主義」の影響を強く受けるよ！</p></blockquote>\n<p>こうして1955年、史上初めてアジア・アフリカ29カ国の首脳が集まり、インドネシアの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バンドン</strong></span>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1回アジア＝アフリカ会議</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バンドン会議</strong></span>】</strong>が開かれたよ。中心となったのは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネルー</strong></span>（インド）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">周恩来</strong></span>（中国）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スカルノ</strong></span>（インドネシア）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナセル</strong></span>（エジプト）などだね。参加国をよく見てみると、<strong class=\"source-bold\">各国の立場はバラバラ</strong>だ。だって中華人民共和国は社会主義だし、フィリピンやトルコは反共軍事同盟に加盟してる。でも、欧米に対する「<strong class=\"source-bold\">反植民地主義</strong>」や「<strong class=\"source-bold\">平和共存</strong>」という点では一致して、「平和五原則」を発展させた「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和十原則</strong></span>」を<ruby>採択<rt>さいたく</rt></ruby>したんだ。</p>\n<p>「平和十原則」の内容に「<strong class=\"source-bold\">国連<ruby>憲章<rt>けんしょう</rt></ruby>の尊重</strong>」や「<strong class=\"source-bold\">人種と国家間の平等</strong>」がある。特に、国連は重要だよ。だって、もと<ruby>宗主国<rt>そうしゅこく</rt></ruby>の欧米諸国より新たに独立したアジア・アフリカ諸国のほうが多いよね。国連加盟国の数なら勝てる！ そして、</p>",
  "439": "<h2>439</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後のインドと第三世界の形成</u></p></blockquote>\n<p>「<strong class=\"source-bold\">非同盟主義</strong>」に基づいて、米ソ両陣営のどちらの同盟にも属さない「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第三世界</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第三勢力</strong></span>】</strong>」を形成したんだ。また、1957年にはエジプトのカイロに49カ国の<strong class=\"source-bold\">民間代表</strong>が集まり、<strong class=\"source-bold\">アジア・アフリカ人民<ruby>連帯<rt>れんたい</rt></ruby>会議</strong>が開かれ、政治的に支配する「<strong class=\"source-bold\">旧植民地主義</strong>」と、旧宗主国が経済的に支配する「<strong class=\"source-bold\">新植民地主義</strong>」にも反対したよ。</p>\n<p>その後の第三世界の動きを一気に見よう！ バンドン会議以降の「非同盟」の動きを受け継いで、1961年には、ユーゴスラヴィアの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベオグラード</strong></span>で<strong class=\"source-bold\">第1回</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">非同盟諸国首脳会議</strong></span>が開かれ、アジア・アフリカに加えて<strong class=\"source-bold\">ラテンアメリカ</strong>などからも参加国が増えたよ。ただ、<strong class=\"source-bold\">インドと対立する中国は代表を送らなかった</strong>。この会議ではインドのネルー、ユーゴのティトー、エジプトのナセルらが中心となり、「非同盟主義」を再確認したうえで、<strong class=\"source-bold\">新・旧の植民地主義への反対</strong>などが宣言された。また、平和共存への努力として、東ドイツのベルリンの<ruby>壁<rt>かべ</rt></ruby>建設［1961］による米ソ対立の激化に対して、まさにリアルタイムで<strong class=\"source-bold\">米ソ両国に対話を促す声明を発表</strong>したんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ネルーの死後、娘のインディラ＝ガンディーが首相となる！</strong></span></h4>\n<p>では、インドに戻るね。ネルーの死後に首相となったシャストリも急死して、1966年には<strong class=\"source-bold\">ネルーの娘インディラ＝ガンディー</strong>が首相となった。ただ、この時期のインドは深刻な経済危機なんだ。前年の<strong class=\"source-bold\">第2次インド＝パキスタン戦争【印パ戦争】</strong>をきっかけに、アメリカがインド・パキスタン両国への経済援助をストップしたから、五カ年計画が行き詰まって食糧危機が起きた。しかも、中国との対立は収まる気配もない。こうした危機を背景に、インディラ＝ガンディーは「<ruby>貧困<rt>ひんこん</rt></ruby>追放」をスローガンに<strong class=\"source-bold\">社会主義的政策</strong>をとり、さらに中国を牽制するため<strong class=\"source-bold\">ソ連に接近</strong>、1971年、ソ連＝インド平和友好協力条約を結んだんだ。</p>\n<p>ただ、インドにとって気がかりだったのは、<strong class=\"source-bold\">中国の<ruby>核<rt>かく</rt></ruby>保有</strong>だ。もし、中国が核兵器を背景に国境紛争で強硬な姿勢をとったら、インドは対抗できない。最初はソ連に「インドをソ連の核兵器で守ってほしい」と頼んだんだけど、ソ連に断られた。「<strong class=\"source-bold\">中国に対抗する</strong>には核開発しかない」と思ったインドは、1974年に<strong class=\"source-bold\"><ruby>原爆<rt>げんばく</rt></ruby>実験</strong>をおこない、6番目の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">核保有国</strong></span>になったんだ。</p>\n<blockquote><p>中ソ対立を背景にソ連に対抗した中国が、そして中印国境紛争を背景に中国に対抗したインドが核保有国になった……。核の拡散が止まらないね</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 第3次印パ戦争でバングラデシュが独立！ 国際関係も整理しよう！</strong></span></h4>\n<p>インドとパキスタンの<strong class=\"source-bold\">カシミール</strong><ruby>帰属<rt>きぞく</rt></ruby>問題、さらに<strong class=\"source-bold\">中ソ対立と中印国境紛争</strong>を背景に、「<strong class=\"source-bold\">ソ連・インド</strong>」「<strong class=\"source-bold\">中国・パキスタン</strong>」が接近したよね。1970年代には、これに新たな対立が加わるんだ。パキスタンはもともと<strong class=\"source-bold\">東西パキスタン</strong>に領土が分かれていたんだけど、東西の共通点は「イスラーム教徒」ということだけ。西（パ</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "440": "<h2>440</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第24回</strong></span> 戦後のインド・東南アジア</p></blockquote>\n<p>ンジャーブ系）はウルドゥー語、東（ベンガル系）はベンガル語というふうに言語も違ったから、本来この2つの地域を1つの国にしたことに問題があるよ。そして、「なんでもかんでも、西を中心に決めるな」って<strong class=\"source-bold\">東パキスタンが反発</strong>して独立運動が起きたから、「パキスタンを弱らせるチャンス！」と考えた<strong class=\"source-bold\">インドが東を支援</strong>して開戦、1971年に<strong class=\"source-bold\">第3次インド＝パキスタン戦争【印パ戦争】</strong>が<ruby>勃発<rt>ぼっぱつ</rt></ruby>した。この戦争でインドが大勝すると、東パキスタンは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バングラデシュ</strong></span>として独立を達成したんだ。そして、パキスタンに対して、圧倒的にインドが優位に立ったんだよ。</p>\n<h4><strong class=\"source-bold\">〈南アジアの国際関係〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><strong class=\"source-bold\">ソ連</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ対立</strong></span><span data-source-color=\"red\" style=\"color:#e52715\">↔</span></td><td><strong class=\"source-bold\">中国</strong></td></tr><tr><td><span data-source-color=\"gray\" data-source-marker=\"curved-line\" style=\"color:#777777\">⌒</span></td><td></td><td><span data-source-color=\"black\" data-source-marker=\"curved-line\" style=\"color:#001000\">⌒</span></td></tr><tr><td><span data-source-color=\"gray\" data-source-marker=\"double-line\" style=\"color:#777777;border-bottom:3px double #777777\">╲</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ国境紛争</strong></span><span data-source-color=\"red\" style=\"color:#e52715\">↕</span></td><td><span data-source-color=\"black\" data-source-marker=\"double-line\" style=\"color:#001000;border-bottom:3px double #001000\">╱</span></td></tr><tr><td><span data-source-border=\"black\" data-source-border-shape=\"circle\" style=\"border:2px solid #001000;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><strong class=\"source-bold\">パキスタン</strong><br><strong class=\"source-bold\">（西パキスタン）</strong></span></td><td><span data-source-border=\"gray\" data-source-border-shape=\"circle\" style=\"border:2px solid #777777;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><strong class=\"source-bold\">インド</strong></span></td><td><span data-source-border=\"gray\" data-source-border-shape=\"circle\" style=\"border:2px solid #777777;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><strong class=\"source-bold\">バングラデシュ</strong><br><strong class=\"source-bold\">（東パキスタン）</strong></span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カシミール帰属問題</strong></span><span data-source-color=\"red\" style=\"color:#e52715\">↔</span></td><td><span data-source-color=\"gray\" data-source-marker=\"double-line\" style=\"color:#777777;border-bottom:3px double #777777\">═</span></td><td><span data-source-color=\"red\" data-source-marker=\"curved-arrow\" data-source-line-style=\"dashed\" style=\"color:#e52715\">↶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">「西」主導に反発</strong></span></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ その後のインド・パキスタンはどうなったんだろう？</strong></span></h4>\n<p>1980年代に入って、<strong class=\"source-bold\">国民会議派の優位が少しずつ崩れ始め</strong>、各地で地方分権を求める声が強まった。そして、北部のパンジャーブ地方で起きたシク教徒の独立運動を<ruby>弾圧<rt>だんあつ</rt></ruby>した<strong class=\"source-bold\">インディラ＝ガンディーが暗殺</strong>されてしまった。彼女の死後、息子の<strong class=\"source-bold\">ラジブ＝ガンディー</strong>が首相となったものの、多数派のヒンドゥー教徒と少数派のムスリムやシク教徒の対立が激しくなり、国民会議派はついに政権を失った。しかも、1991年には選挙運動中に<strong class=\"source-bold\">ラジブも暗殺</strong>されたんだ。1990年代に入ると<strong class=\"source-bold\">ヒンドゥー至上主義【ヒンドゥー民族主義】</strong>を掲げる<strong class=\"source-bold\">インド人民党</strong>が勢力を伸ばし、1998年には<strong class=\"source-bold\">バジパイ【</strong>ヴァージペーイ<strong class=\"source-bold\">】</strong>が首相となった。ヒンドゥー至上主義は、「ヒンドゥー（インド）民族」の一致団結を主張する運動で、ヒンドゥー教徒だけじゃなくて、インドで生まれたシク教徒やジャイナ教徒なども含めるんだけど、外来のイスラーム教やキリスト教には敵対的なんだ。近年のインドは、国民会議派とインド人民党が政権交代をしながら、<strong class=\"source-bold\">経済の自由化や外資の導入で、IT産業を中心に急成長</strong>しているね。</p>\n<p>それから、インド・パキスタンの対立が、<strong class=\"source-bold\"><ruby>核<rt>かく</rt></ruby>戦争の危険</strong>もはらむものになった。1998年、バジパイ政権のもとで<strong class=\"source-bold\">インドが核実験を強行</strong>すると、これに対抗した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パキスタンも核実験</strong></span>をおこなって、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">核保有国</strong></span>になった。インドに対して劣勢に立たされ続けたパキスタンでは、伝統的に<strong class=\"source-bold\">軍部の力が強く政党が弱い</strong>ので、1988年から1999年まではちゃんと選挙をやっていたんだけど、1999年には再びクーデタで軍政に戻っちゃった。しかも、2007年にはイスラーム圏初の女性首相だった<strong class=\"source-bold\">ベナジル＝ブット</strong> <strong class=\"source-bold\">元首相が暗殺</strong>されるなど、政局は混迷を深めている。パキスタンの持つ危険性は、「<strong class=\"source-bold\">核保有国が軍事政権</strong>」という事実だよ。</p>",
  "441": "<h2>441</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">インドシナ戦争とベトナム戦争</u></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">インドシナ戦争とベトナム戦争</strong></span></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"background-color:#fbe1e1\"><strong class=\"source-bold\">インドシナ戦争</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td>〈北ベトナム（社会主義陣営）〉</td><td>〈南ベトナム（資本主義陣営）〉</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム独立同盟</strong></span>結成［1941］</td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム民主共和国</strong></span>建国［1945.9］</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>初代大統領<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ホー＝チ＝ミン</strong></span>［任1945〜69］</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>首都：<strong class=\"source-bold\">ハノイ</strong></td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">➡</span>フランスからの独立を宣言</td><td></td></tr></tbody></table></div>\n<blockquote><p><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドシナ戦争</strong></span>［1946〜54］</span></p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td></td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム国</strong></span>成立［1949.6］</td></tr><tr><td></td><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>主席：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バオダイ</strong></span>（<ruby>阮<rt>げん</rt></ruby>朝最後の王）</td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\">ソ連</span><span data-source-color=\"gray\" style=\"color:#777777\">━</span><br><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\">中国</span><span data-source-color=\"gray\" style=\"color:#777777\">━</span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\">ベトナム民主共和国</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">↔</span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\">ベトナム国</span></td><td><span data-source-color=\"gray\" style=\"color:#777777\">━</span><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\">仏</span><span data-source-color=\"gray\" style=\"color:#777777\">━</span><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\">米</span></td></tr></tbody></table></div>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ディエンビエンフーの戦い</strong></span>［1954.5］</p>\n<p><strong class=\"source-bold\">フランス軍が大敗</strong><span data-source-color=\"green\" style=\"color:#315837\">➡</span>休戦の契機</p>\n<p><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジュネーヴ休戦協定</strong></span>［1954.7］</span></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北緯17度線</strong></span>を<ruby>暫定<rt>ざんてい</rt></ruby>軍事境界線</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">フランス軍が撤退</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>撤退後に<strong class=\"source-bold\">南北統一選挙</strong>を実施</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">米とバオダイ政府は調印を拒否</strong></p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ベトナム民主共和国の独立に対しフランスが<ruby>侵攻<rt>しんこう</rt></ruby>、インドシナ戦争が始まる！</strong></span></h4>\n<p>第二次世界大戦中、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ホー＝チ＝ミン</strong></span>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム独立同盟</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトミン</strong></span>】</strong>を結成して<ruby>抗日<rt>こうにち</rt></ruby>ゲリラ闘争を展開すると、日本の敗戦直後の<strong class=\"source-bold\">八月革命</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハノイ</strong></span>を首都とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム民主共和国</strong></span>を建てて、フランスからの独立を宣言した。初代大統領となった<strong class=\"source-bold\">ホー＝チ＝ミンは共産党の指導者</strong>だから<strong class=\"source-bold\">社会主義国</strong>だね。でも、北からの中国軍（まだ国民党政権だよ）の侵攻や<strong class=\"source-bold\">地主や資本家の反発</strong>もあって、国内は分裂状態だった。フランスは北部（ベトナム民主共和国）のフランス連合内での独立を</p>\n<blockquote><p><ruby>冷戦<rt>れいせん</rt></ruby>が実際の「<ruby>熱<rt>あつ</rt></ruby>い戦争」になっちゃった……。このあとベトナムは、長い戦争の時代になるんだ</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "442": "<h2>442</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第24回</strong></span> 戦後のインド・東南アジア</p></blockquote>\n<p>承認したんだけど、中部や南部をめぐる交渉は決裂、植民地支配の復活を狙った<strong class=\"source-bold\">フランス軍がベトナムに<ruby>侵攻<rt>しんこう</rt></ruby></strong>した。こうして1946年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドシナ戦争</strong></span>が<ruby>勃発<rt>ぼっぱつ</rt></ruby>したんだ。</p>\n<p>開戦当初、フランス軍は大都市や主要道路などの重要拠点を一気におさえた。でも、<strong class=\"source-bold\">ホー＝チ＝ミンら共産勢力</strong>は、<strong class=\"source-bold\">山間部を拠点</strong>に抵抗を続けたんだ。フランス軍は、山間部に入ると激しい逆襲を受けて敗退し、ベトナムは分裂状態になった。フランスはベトナムの分割を考えていたけど、<strong class=\"source-bold\">ホー＝チ＝ミンは統一を要求</strong>して一歩も譲らない。そこで、フランスは「地主や資本家など<strong class=\"source-bold\">資本主義側のベトナム人の国をつくる</strong>」として、1949年、南部に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バオダイ</strong></span>（<ruby>阮<rt>げん</rt></ruby>朝最後の王）を主席とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム国</strong></span>を建て、<strong class=\"source-bold\">ベトナム国（南ベトナム）を通じて軍事<ruby>介入<rt>かいにゅう</rt></ruby></strong>を強めたんだ。</p>\n<p>こうしてインドシナ戦争は、単なるベトナムの独立戦争から「<strong class=\"source-bold\">資本主義 vs. 社会主義</strong>」の戦争に変わり始めたんだ。しかも1949年に成立した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華人民共和国</strong></span>は<strong class=\"source-bold\">北ベトナムへの全面支援</strong>を打ち出し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span>も<strong class=\"source-bold\">北ベトナムへの支援</strong>を開始、これに対し、共産主義の拡大を阻止したい<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ</strong></span>も<strong class=\"source-bold\">ベトナム国（南ベトナム）を承認</strong>して全面援助を約束した。そして米ソ両国の支援を受けた南北ベトナムの戦闘は、どちらも決め手がないまま<ruby>膠着<rt>こうちゃく</rt></ruby>状態になった。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ついにフランスが<ruby>撤退<rt>てったい</rt></ruby>を決め、ジュネーヴ休戦協定が成立！</strong></span></h4>\n<p>スターリンの死をきっかけに朝鮮戦争の休戦が成立すると、1954年4月には<strong class=\"source-bold\">米、英、ソ、仏、中、ベトナム民主共和国、ベトナム国</strong>などの代表が<strong class=\"source-bold\">ジュネーヴ</strong>に集まって<strong class=\"source-bold\">インドシナ戦争の休戦に向けた会議</strong>が始まった。会議の開催中もフランスはアメリカの援助を受けて反撃のチャンスを狙っていたんだけど、逆に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ディエンビエンフーの戦い</strong></span>で大敗した！。しかも、国内で反戦の世論が高まり、しかも財政が<ruby>破<rt>は</rt></ruby><ruby>綻<rt>たん</rt></ruby>寸前……。ついに<strong class=\"source-bold\">フランスはベトナムからの撤退を決めた</strong>んだ。</p>\n<p>こうして、同年7月に結ばれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジュネーヴ休戦協定</strong></span>では、まず<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北緯17度線</strong></span>を<strong class=\"source-bold\"><ruby>暫定<rt>ざんてい</rt></ruby>軍事境界線</strong>として、とりあえず北をベトナム民主共和国、南をベトナム国としたうえで、1956年までに<strong class=\"source-bold\">フランス軍が撤退</strong>し、1957年に<strong class=\"source-bold\">南北統一選挙</strong>を実施して新政権を樹立することになった。さらにフランスは<strong class=\"source-bold\">ラオスとカンボジア</strong>の独立も承認した。しかし、<strong class=\"source-bold\">バオダイ政府（ベトナム国）は調印を拒否</strong>し、<strong class=\"source-bold\">アメリカも最終宣言への参加を拒否</strong>した。せっかくインドシナ戦争が終わったのに、今度はフランスにかわって<strong class=\"source-bold\">アメリカがベトナム問題に直接介入</strong>することになっちゃった。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ アメリカがベトナム共和国を建てると、反発した解放勢力が結集！</strong></span></h4>\n<p><strong class=\"source-bold\">ジュネーヴ休戦協定の調印を拒否したアメリカ</strong>は、1954年に<ruby>ANZUS<rt>アンザス</rt></ruby> <strong class=\"source-bold\">加盟国と英仏、フィリピン、タイ、パキスタン</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東南アジア条約機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>SEATO<rt>シアトー</rt></ruby></strong></span>】</strong>を結成して北ベトナム包囲網をつくると、1955年には<strong class=\"source-bold\">南部</strong>に、バオダイにかわって<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴ＝ディン＝ジエム</strong></span>を大統領とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム共和国</strong></span>を建て、休戦協定で決められた<strong class=\"source-bold\">南北統一選挙も拒否</strong>した。そもそも休戦協定に調印していないけどさ。そして、<strong class=\"source-bold\">ジエム政権はアメリカの支援に依存</strong>しながら、反対派を<ruby>弾圧<rt>だんあつ</rt></ruby>して権力を維持したんだ。</p>",
  "443": "<h2>443</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">インドシナ戦争とベトナム戦争</u></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"background-color:#fbe1e1\"><strong class=\"source-bold\">ベトナム戦争</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td>〈北ベトナム（社会主義陣営）〉</td><td>〈南ベトナム（資本主義陣営）〉</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>北はホー＝チ＝ミンのもとで社会主義建設</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム共和国</strong></span>成立［1955］</td></tr><tr><td></td><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>大統領：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴ＝ディン＝ジエム</strong></span></td></tr><tr><td></td><td><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">アメリカが全面支援</strong></td></tr></tbody></table></div>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南ベトナム解放民族戦線</strong></span>結成［1960］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>ゴ＝ディン＝ジエム政権の打倒を目指して結成</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">内戦勃発</strong>（広義の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム戦争</strong></span>［1960〜75］）</p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">ホー＝チ＝ミン＝ルート</strong>の建設</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">南ベトナム＝クーデタ</strong>［1963.11］</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">南ベトナム解放民族戦線を支援</strong></td><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">ゴ＝ディン＝ジエム暗殺</strong></td></tr><tr><td></td><td><span data-source-color=\"green\" style=\"color:#315837\">➡</span>以後、クーデタが<ruby>頻発<rt>ひんぱつ</rt></ruby></td></tr></tbody></table></div>\n<blockquote><p><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">アメリカ軍の本格的介入</strong>（狭義の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム戦争</strong></span>［1965〜73］）</span></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北ベトナム爆撃</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>北爆<rt>ほくばく</rt></ruby></strong></span>】</strong>の開始［1965.2］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>アメリカ大統領<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョンソン</strong></span>による</p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td></td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム反戦運動</strong></span>激化</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">ホー＝チ＝ミンの死</strong>［1969］</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>アメリカ合衆国の<strong class=\"source-bold\">財政赤字の拡大</strong></td></tr></tbody></table></div>\n<blockquote><p><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム和平協定</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ和平協定</strong></span>】</strong>［1973.1］</span></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">アメリカ軍の撤退</strong>を決定</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>ただし、戦闘は継続（「<strong class=\"source-bold\">ベトナム化</strong>」）</p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td></td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">サイゴン陥落</strong>［1975.4］</td></tr></tbody></table></div>\n<p>一方、北ベトナムは軍事行動を起こす余裕はなかったんだけど、ベトナム労働党（かつてのインドシナ共産党）はとにかく<strong class=\"source-bold\">南ベトナムのなかにいる解放勢力を結集</strong>して対抗、グエン＝フー＝トを議長とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南ベトナム解放民族戦線</strong></span>が結成されて、<strong class=\"source-bold\">共産主義者・民族主義者・仏教徒・カトリック教徒・農民</strong>など、<strong class=\"source-bold\">ジエム政権とアメリカの介入に反対</strong>する解放勢力を結集した。さらに北ベトナムは、<strong class=\"source-bold\">カンボジア・ラオスを経由するホー＝チ＝ミン＝ルート</strong>を建設して解放勢力を支援し、武器の援助を受けた解放民族戦線によるゲリラ戦が始まり、農民の支持で勢力を拡大した。こうして<strong class=\"source-bold\">南ベトナムは内戦</strong>となった。<strong class=\"source-bold\">1960年の内戦開始から75年のサイゴン<ruby>陥落<rt>かんらく</rt></ruby>まで</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "444": "<h2>444</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第24回</strong></span> 戦後のインド・東南アジア</p></blockquote>\n<p>を、広い意味では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム戦争</strong></span>と呼ぶんだ。アメリカは武器援助などで南ベトナム政府（ジエム政権）を支援した。ただ、ソ連や中国との直接戦争に拡大しないよう<strong class=\"source-bold\">米軍の直接派兵はしなかった</strong>から、政府軍は解放民族戦線に勝てず、さらに<strong class=\"source-bold\">各地で反政府運動も起こり</strong>、仏教徒のデモでは<ruby>僧侶<rt>そうりょ</rt></ruby>の焼身自殺なども相次いだ。もはや政権が維持できないと思ったアメリカは、クーデタで<strong class=\"source-bold\">ゴ＝ディン＝ジエムを暗殺</strong>させた（<strong class=\"source-bold\">南ベトナム＝クーデタ</strong>）。しかし、これ以後<strong class=\"source-bold\">ベトナム共和国は一気に弱体化</strong>し、約1年半の間で13回もクーデタが起こる異常事態！。もはや解放民族戦線の勢力拡大は抑えられない。<strong class=\"source-bold\">アメリカは本格的な<ruby>介入<rt>かいにゅう</rt></ruby>を決意</strong>したんだ。</p>\n<h4><strong class=\"source-bold\">〈ベトナム戦争関連〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">ラオス</strong></td><td><strong class=\"source-bold\">ベトナム</strong></td></tr><tr><td><strong class=\"source-bold\">カンボジア</strong></td><td><span data-source-color=\"green\" data-source-marker=\"point\" data-source-outline-color=\"black\" style=\"color:#315837\">●</span>ハノイ</td></tr><tr><td><span data-source-color=\"green\" data-source-marker=\"point\" data-source-outline-color=\"black\" style=\"color:#315837\">●</span>サイゴン</td><td><span data-source-color=\"brown\" style=\"color:#a43725\">━</span>北緯17°</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ディエンビエンフーの戦い［1954］</span></td><td><span data-source-color=\"red\" data-source-marker=\"battle\" style=\"color:#e52715\">⚔</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">トンキン湾事件［1964］</span></td><td><span data-source-color=\"red\" data-source-marker=\"battle\" style=\"color:#e52715\">⚔</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ホー＝チ＝ミン＝ルート</span></td><td><span data-source-color=\"red\" data-source-marker=\"curved-arrow\" data-source-line-style=\"dashed\" style=\"color:#e52715\">⇢ ⇢ ⇢ ⇢ ⇢</span></td></tr></tbody></table></div>\n<blockquote><p>いよいよアメリカ軍が直接介入してくるよ。でも、ホー＝チ＝ミンは負けない！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ アメリカの直接介入でベトナム戦争が<ruby>勃発<rt>ぼっぱつ</rt></ruby>！ しかし、泥沼の戦争へ</strong></span></h4>\n<p>1964年、アメリカは海軍の艦艇が<ruby>魚雷<rt>ぎょらい</rt></ruby>攻撃を受けた事件（<strong class=\"source-bold\">トンキン湾事件</strong>）を口実に、<strong class=\"source-bold\">北ベトナムへの爆撃</strong>をおこなった。そして、アメリカの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョンソン</strong></span>大統領は議会に対し「<strong class=\"source-bold\">ベトナム攻撃への白紙委任</strong>を与えてほしい」と要請し、議会もほぼ全会一致でこれを認めた。こうして、1965年には本格的な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北ベトナム爆撃</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>北爆<rt>ほくばく</rt></ruby></strong></span>】</strong>が開始され、アメリカ軍の本格的な直接介入が始まった。<strong class=\"source-bold\">1965年の北爆開始から73年のアメリカ軍撤退まで</strong>を、狭い意味では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム戦争</strong></span>と呼ぶんだ。北爆開始後、すぐさま<strong class=\"source-bold\">海兵隊がベトナムに上陸</strong>、これに続いて反共同盟を結ぶ<strong class=\"source-bold\">韓国軍、オーストラリア軍、ニュージーランド軍</strong>もベトナムに送られた。一方の北ベトナムは、ホー＝チ＝ミンが総力戦を呼びかけ、<strong class=\"source-bold\">ソ連や中国も全面的に北ベトナムを支援</strong>した。そして、北ベトナムから南ベトナムへと送られた兵力は30万人以上になった。</p>\n<p>アメリカは、最新兵器を駆使した<strong class=\"source-bold\">大規模な空爆や50万人を超える地上軍を投入</strong>し</p>",
  "445": "<h2>445</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">インドシナ戦争とベトナム戦争</u></p></blockquote>\n<p>たにもかかわらず、決定的な勝利を得るどころか、多数の戦死者を出す結果にしかならなかった。だって、<strong class=\"source-bold\">北ベトナムと解放民族戦線は山間部を拠点</strong>にアメリカ軍を山のなかに誘い込んで、爆弾から銃から<ruby>手榴弾<rt>しゅりゅうだん</rt></ruby>から落とし穴まで駆使して反撃する作戦なんだもん……！。兵力を分散させられた米軍は、各地で追い詰められた。行き詰まったアメリカは、解放勢力の拠点を<ruby>潰<rt>つぶ</rt></ruby>すために<strong class=\"source-bold\">森林にダイオキシン類を含む有害な農薬を<ruby>撒<rt>ま</rt></ruby>く「<ruby>枯<rt>か</rt></ruby>れ<ruby>葉<rt>は</rt></ruby>作戦」</strong>など、人道に反するような攻撃もおこなったんだ。「枯れ葉剤」による深刻な環境破壊で、ベトナムでは現在でも<ruby>胎児<rt>たいじ</rt></ruby>の奇形などが問題になっている。そして、1968年1月には、北ベトナム軍と解放民族戦線軍が米軍施設や南ベトナムの主要都市を一斉に総攻撃した。この<strong class=\"source-bold\">テト攻勢</strong>（テトは旧正月のことね）は結局うまくいかなかったんだけど、アメリカ軍も1万人以上の犠牲者を出した。<strong class=\"source-bold\">アメリカは泥沼の戦争に引きずり込まれていった</strong>んだ。</p>\n<h4><strong class=\"source-bold\">〈ベトナム戦争の対立関係〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"brown\" data-source-border-width=\"thick\" style=\"border:3px solid #a43725;padding:0 0.2em\"><strong class=\"source-bold\">ソ連</strong></span><span data-source-color=\"brown\" style=\"color:#a43725\">━</span><br>中ソ対立<span data-source-color=\"gray\" style=\"color:#777777\">↕</span><br><span data-source-border=\"pink\" data-source-border-width=\"thick\" style=\"border:3px solid #f0a0a0;padding:0 0.2em\"><strong class=\"source-bold\">中国</strong></span><span data-source-color=\"pink\" style=\"color:#f0a0a0\">━</span></td><td><span data-source-border=\"brown\" data-source-border-width=\"thick\" style=\"border:3px solid #a43725;padding:0 0.2em\"><strong class=\"source-bold\">ベトナム民主共和国</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">↔</span><span data-source-border=\"black\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ベトナム共和国</strong><br><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">南ベトナム政府</strong></span><span data-source-color=\"black\" style=\"color:#001000\">━</span><br><span data-source-color=\"red\" style=\"color:#e52715\">↕</span><br><span data-source-border=\"brown\" data-source-border-style=\"solid\" style=\"border:1px solid #a43725;padding:0 0.2em\"><strong class=\"source-bold\">南ベトナム解放民族戦線</strong></span></span><span data-source-color=\"red\" style=\"color:#e52715\">↔</span></td><td><span data-source-border=\"black\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">アメリカ</strong></span></td></tr><tr><td></td><td><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">ホー＝チ＝ミン＝ルート</strong></span><span data-source-color=\"brown\" style=\"color:#a43725\">━</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">↔</span></td><td></td></tr></tbody></table></div>\n<blockquote><p>戦争が終わったら、ソ連と中国は北ベトナムに「オマエはどっちにつくんだ！」って、絶対言ってくるよ</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 反戦運動の拡大と財政難で、ついにアメリカ軍が撤退！</strong></span></h4>\n<p>さらに、開戦直後から始まった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム反戦運動</strong></span>は、アメリカ国内だけでなく全世界に広がって<strong class=\"source-bold\">アメリカの国際的な孤立</strong>を招いた。特に、1968年に米兵が婦人・子どもを含む村人を殺害した<strong class=\"source-bold\">ソンミ虐殺事件</strong>は世界中から非難を受けた。しかも、<strong class=\"source-bold\">戦費の増大で深刻な財政難</strong>となったアメリカは、もはや戦争を続けられない。こうしてジョンソン大統領が<strong class=\"source-bold\">北爆の部分停止</strong>を発表し、<strong class=\"source-bold\">アメリカと北ベトナム</strong>による<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ和平会談</strong></span>が始まった。さらにジョンソン大統領は、<strong class=\"source-bold\">北爆全面停止</strong>と、<strong class=\"source-bold\">南ベトナム解放民族戦線と南ベトナム政府を加えた4者会談</strong>を提案したんだ。</p>\n<p>1969年、アメリカでは<strong class=\"source-bold\">ベトナム撤退を公約</strong>に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニクソン</strong></span>が大統領となり、米軍撤退の準備が始まったよ。ただ、ニクソンは、<strong class=\"source-bold\">米軍撤退後もベトナム人同士の戦争を続</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "446": "<h2>446</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第24回</strong></span> 戦後のインド・東南アジア</p></blockquote>\n<p><strong class=\"source-bold\">けさせる</strong>、「戦争の“<strong class=\"source-bold\">ベトナム化</strong>”」を狙って、南ベトナム政府軍を強化した。さらに、解放勢力への援助ルートを断絶するために<strong class=\"source-bold\">ラオスやカンボジアにも<ruby>侵攻<rt>しんこう</rt></ruby></strong>、そして、北ベトナムをもう少し弱らせるために<strong class=\"source-bold\"><ruby>北爆<rt>ほくばく</rt></ruby>も再開</strong>した。でも、アメリカの思いどおりにはならなかったんだ。1971年、アメリカの<strong class=\"source-bold\">貿易収支が赤字に転落</strong>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドル危機</strong></span>を招き、もはや財政的に限界になったんだ <span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➡P.404〜405</span>。</p>\n<p>1973年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム和平協定</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ和平協定</strong></span>】</strong>が結ばれて、<strong class=\"source-bold\">アメリカ軍は撤退</strong>したよ。ただ、南ベトナムへの武器支援は続いていたから、<strong class=\"source-bold\">戦争そのものは終わらなかった</strong>。アメリカが撤退すると<strong class=\"source-bold\">解放民族戦線は猛反撃</strong>を開始、<strong class=\"source-bold\">北ベトナム軍も南下</strong>して、ついに1975年4月、南ベトナムの首都<strong class=\"source-bold\">サイゴンが<ruby>陥落<rt>かんらく</rt></ruby></strong>して、<strong class=\"source-bold\">ベトナムは南北統一を実現</strong>したんだよ。残念ながら、この場所にホー＝チ＝ミンはいない……。ずっとベトナムのために戦い続けたホー＝チ＝ミンは、アメリカの撤退もベトナムの統一も見ないまま1969年に亡くなっている。そして統一後、サイゴンは「<strong class=\"source-bold\">ホー＝チ＝ミン市</strong>」と改称されたんだ。</p>\n<blockquote><p>サイゴンの陥落を、ホー＝チ＝ミンに見せてあげたかったよ……</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 統一後のベトナムは、ソ連の援助で社会主義建設を進めた！</strong></span></h4>\n<p>1976年、<strong class=\"source-bold\">南北統一選挙を実施</strong>したベトナムは、統一国会で<strong class=\"source-bold\">新憲法を制定</strong>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム社会主義共和国</strong></span>として、<strong class=\"source-bold\">正式に南北統一</strong>を宣言したよ。最初はソ連・中国のどっちにつこうか決めてなかったけど、中国とアメリカが接近し始めたから、ベトナムとしては我慢ならない。<strong class=\"source-bold\">アメリカと中国に対抗</strong>してソ連寄りに大きく傾き、1978年には<strong class=\"source-bold\">コメコンに加盟</strong>し、さらに<strong class=\"source-bold\">ソ連＝ベトナム友好協力条約</strong>を結んだ。すると、ベトナムのソ連への接近に怒った<strong class=\"source-bold\">中国</strong>が、<strong class=\"source-bold\">カンボジアのポル＝ポト政権を支援</strong>して、ベトナムを挟み撃ちにしようとした。こうして「<strong class=\"source-bold\">ソ連・ベトナム</strong> vs. <strong class=\"source-bold\">中国・アメリカ</strong>」という図式ができあがった。</p>\n<p>そして、ソ連の支援を受けた<strong class=\"source-bold\">ベトナム軍がカンボジアに侵攻</strong>して<strong class=\"source-bold\">ヘン＝サムリン</strong>政権を立てると、いよいよ怒った<strong class=\"source-bold\">中国がベトナムに侵攻</strong>、1979年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>中越<rt>ちゅうえつ</rt></ruby>戦争</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国＝ベトナム戦争</strong></span>】</strong>が<ruby>勃発<rt>ぼっぱつ</rt></ruby>した。たださぁ……ベトナムってアメリカ軍に勝ったんだよ、そりゃ<strong class=\"source-bold\">中国軍くらい撃退できる</strong>。一番迷惑をこうむったのはカンボジアだよ……。ベトナムのカンボジア侵攻や中越戦争で、<strong class=\"source-bold\">ベトナム・カンボジア難民</strong>が大量に発生したんだからさ。</p>",
  "447": "<h2>447</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の東南アジア</u></p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ソ連のペレストロイカ、中国の「改革・開放」の影響がベトナムにも！</strong></span></h4>\n<p>ソ連の援助で社会主義建設を進めたベトナムでは、相次ぐ戦争と周辺国からの孤立で、<strong class=\"source-bold\">経済的には危機的な状況</strong>だった。こうしたなかで最高指導者となったグエン＝ヴァン＝リンは、「ソ連はペレストロイカを始めたし、中国は改革・開放で成果を上げている。停滞を打破するためには、<strong class=\"source-bold\">ベトナムも<ruby>市場<rt>しじょう</rt></ruby>経済を導入</strong>しよう！」と考えて、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイモイ</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>刷新<rt>さっしん</rt></ruby></strong></span>】</strong>を開始した。これは<strong class=\"source-bold\">市場経済を導入</strong>するとともに、外国資本も導入して生産を拡大するっていう、<strong class=\"source-bold\">ベトナム版の「改革・開放」政策</strong>だよ。さらに、<ruby>冷戦<rt>れいせん</rt></ruby>終結後には、<strong class=\"source-bold\">経済活動の自由と平等の保障</strong>も決まり、市場経済を認めた新憲法も制定されたんだよ。</p>\n<p>また、外交でも<strong class=\"source-bold\">ソ連の「新思考外交」</strong>を背景に<strong class=\"source-bold\">カンボジアから撤退</strong>したことで、1991年には<strong class=\"source-bold\">中国との国交正常化</strong>、1995年には<strong class=\"source-bold\">アメリカとの国交正常化</strong>も実現し、各国からの援助も受けられるようになった。そして、念願の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>ASEAN<rt>アセアン</rt></ruby>への加盟</strong></span>も実現すると、急速な経済発展を遂げたんだ。</p>\n<p>その後、1997年の<strong class=\"source-bold\">アジア通貨危機</strong>の影響を受けて、一時は経済成長にブレーキがかかったものの、マジメで勤勉なベトナム人気質もあって外国企業の進出も加速し、21世紀に入って、あらたな経済成長の段階に入っているよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">戦後の東南アジア</strong></span></h3>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈インドネシア〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 建国の父スカルノの政策は、「反米・<ruby>容共<rt>ようきょう</rt></ruby>・親中国」だ！</strong></span></h4>\n<p>1945年、<strong class=\"source-bold\">建国五原則</strong>（最高神〔<ruby>唯一神<rt>ゆいいつしん</rt></ruby>〕への信仰、民族主義、人道主義、民主主義、社会主義）を発表した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スカルノ</strong></span>は、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア共和国</strong></span>の独立を宣言すると<strong class=\"source-bold\">初代大統領</strong>になった。ただ、オランダはこれを認めなかったから、そのまま<strong class=\"source-bold\">独立戦争に突入</strong>、4年間の戦争を経て、1949年の<strong class=\"source-bold\">ハーグ協定でオランダからの独立</strong>を勝ち取った。そして、1955年にインドネシアの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バンドン</strong></span>で開かれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1回アジア・アフリカ会議</strong></span>では、インドのネルーや中国の<ruby>周恩来<rt>しゅうおんらい</rt></ruby>とともに<strong class=\"source-bold\">非同盟諸国のリーダー</strong>として活躍し、スカルノは<strong class=\"source-bold\">中国と協調して非同盟政策を推進</strong>することになったんだ。</p>\n<blockquote><p>スカルノが「反米・容共」、スハルトが「親米・反共」がポイントだ！</p></blockquote>\n<p>スカルノの国づくりで一番の問題は、これまでの民族運動で形成された複数の団体をどうやってまとめるか、ということだ。<strong class=\"source-bold\">エリートを中心</strong>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア国民党</strong></span>、<strong class=\"source-bold\">ムスリム商人を中心</strong>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サレカット＝イスラム</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イスラーム同盟</strong></span>】</strong>、そして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア共産党</strong></span>。もし、インドネシアに「資本主義 vs. 社会主義」の<ruby>冷戦<rt>れいせん</rt></ruby>構造を持ち込んだら、国内はバラバラになる。そこでスカルノは「NASAKOM <strong class=\"source-bold\">【ナサコム体制】</strong>」を提唱、国内では<strong class=\"source-bold\">国民党</strong>（NAS）・<strong class=\"source-bold\">イスラーム</strong>（A）・<strong class=\"source-bold\">共産党</strong>（KOM）</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "448": "<h2>448</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第24回</strong></span> 戦後のインド・東南アジア</p></blockquote>\n<p>が連携する「<strong class=\"source-bold\">容共</strong>（共産主義を容認）」政策をとって国内を統合し、対外的には「<strong class=\"source-bold\">反米・親中国</strong>」を原則に非同盟主義をとった。また、<strong class=\"source-bold\">カリマンタン島（マレーシアではボルネオ島と呼ぶよ）の国境問題</strong>で対立する<strong class=\"source-bold\">マレーシア</strong>（インドネシアは承認していなかった）が国連<ruby>安保理<rt>あんぽり</rt></ruby>の非常任理事国に当選したのに反発して、1965年には<strong class=\"source-bold\">国連を脱退</strong>しちゃったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 右派のスハルトがクーデタで権力を握り、「親米・反共」に転換！</strong></span></h4>\n<p>ただ、インドネシアもベトナム戦争の影響から逃れられなかった。1965年、アメリカがベトナムに本格<ruby>介入<rt>かいにゅう</rt></ruby>すると、<strong class=\"source-bold\">右派軍人によるクーデタ</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>九<rt>く</rt></ruby>・<ruby>三〇<rt>さんじゅう</rt></ruby>事件</strong></span>）によって<strong class=\"source-bold\">共産党が<ruby>潰<rt>つぶ</rt></ruby>され</strong>、<strong class=\"source-bold\">スカルノが失脚</strong>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スハルト</strong></span>が権力を掌握した。スカルノの失脚は、<strong class=\"source-bold\">ベトナム戦争の<ruby>勃発<rt>ぼっぱつ</rt></ruby>で反共主義が強まった</strong>ことが大きな原因だけど、<ruby>華僑<rt>かきょう</rt></ruby>と対立するムスリム商人がスカルノの親中国政策に反発したことも一因だよ。</p>\n<p>政権に<ruby>就<rt>つ</rt></ruby>いたスハルトは「<strong class=\"source-bold\">親米・反共</strong>」政策に転換すると、西側の資本を導入し、<strong class=\"source-bold\">開発独裁体制</strong>をとって積極的な経済発展を図ったよ。対外的にはアメリカとの関係を強め、1966年には<strong class=\"source-bold\">国連に復帰</strong>するとともに、<strong class=\"source-bold\">アメリカのベトナム政策に協力</strong>するために<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ASEAN</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東南アジア諸国連合</strong></span>】</strong>を結成して、北ベトナム包囲網を形成したんだ。このあと、インドネシアはアメリカなどの援助で経済発展したけど、ウラでは<strong class=\"source-bold\">スハルト一族がインドネシア経済の利権を独占</strong>して、<ruby>汚職<rt>おしょく</rt></ruby>・<ruby>腐敗<rt>ふはい</rt></ruby>が広がっていた。そして、1997年の<strong class=\"source-bold\">アジア通貨危機</strong>で経済が混乱すると、汚職や腐敗が一気に表面化して、翌年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スハルトは退陣</strong></span>に追い込まれた。</p>\n<p>その後、2001年にはスカルノの長女<strong class=\"source-bold\">メガワティ</strong>が大統領となり経済の再建を目指したけど、アチェ独立を目指すイスラーム過激派のテロや官僚の汚職で、国内の混乱は収まらなかった。そして、2004年に大統領となった<strong class=\"source-bold\">ユドヨノ</strong>は武装組織と和解し、<strong class=\"source-bold\">アチェ独立運動</strong>を終結させたんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ インドネシアの抱える独立問題。21世紀に入って東ティモールが独立！</strong></span></h4>\n<p>インドネシアというのは、もともとは「<strong class=\"source-bold\">オランダ領東インド</strong>」が独立してできた国だけど、大航海時代に最初にこの地域にきたのはポルトガルだから、<strong class=\"source-bold\">ポルトガル領もあった</strong>。1974年に<strong class=\"source-bold\">ポルトガル本国で軍事独裁政権が倒れる</strong>と（「カーネーション革命」）、その影響で1975年に<strong class=\"source-bold\">東ティモールがポルトガルから独立</strong>したんだけど、翌年、島の西側を領有していた<strong class=\"source-bold\">インドネシアが軍事<ruby>侵攻<rt>しんこう</rt></ruby>して<ruby>併合<rt>へいごう</rt></ruby>を宣言</strong>、スハルト政権は独立運動を武力で抑え込んだ。しかし、スハルトの失脚で東ティモールの独立運動が再び盛り上がって、1999年には住民投票を実施して<strong class=\"source-bold\">インドネシアからの独立を宣言</strong>したんだ。ただ、独立宣言の直後から反対派と賛成派が衝突して、<strong class=\"source-bold\">東ティモール内戦</strong>が勃発したよ。この内戦では、独立反対派を支援してインドネシアが介入する一方、国連は独立に向けて多国籍軍を派遣し、<strong class=\"source-bold\">国連東ティモール<ruby>暫定統治<rt>ざんていとうち</rt></ruby>機構</strong>の設置などを経て、2002年、<strong class=\"source-bold\">東ティモールは正式に独立</strong>を達成したよ。</p>",
  "449": "<h2>449</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の東南アジア</u></p></blockquote>\n<h4><strong class=\"source-bold\">〈戦後の東南アジア〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td>ビルマ（ミャンマー）</td><td>ラオス</td></tr><tr><td>ベトナム</td><td>タイ</td></tr><tr><td>カンボジア</td><td><strong class=\"source-bold\">フィリピン</strong></td></tr><tr><td>ブルネイ＝ダルサラーム</td><td>サバ</td></tr><tr><td><strong class=\"source-bold\">マレーシア</strong></td><td>サラワク</td></tr><tr><td><span data-source-color=\"pink\" data-source-marker=\"point\" data-source-outline-color=\"black\" style=\"color:#f0a0a0\">●</span>シンガポール</td><td>カリマンタン（ボルネオ）島</td></tr><tr><td><strong class=\"source-bold\">インドネシア</strong></td><td>東ティモール</td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"pink\" data-source-marker=\"area\" data-source-outline-color=\"black\" style=\"color:#f0a0a0\">■</span></td><td>ASEANの原加盟国</td></tr><tr><td><span data-source-color=\"gray\" data-source-marker=\"area\" data-source-outline-color=\"black\" style=\"color:#777777\">■</span></td><td>あとからASEANに加盟した国</td></tr></tbody></table></div>\n<blockquote><p>東南アジアは、すべての国がASEANに加盟しているよ！ もう軍事同盟じゃないもんね</p></blockquote>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈カンボジア・ラオス〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ フランスから独立したものの……ベトナムの問題に巻き込まれる！</strong></span></h4>\n<p>第二次世界大戦後、<strong class=\"source-bold\">カンボジアもフランスから独立</strong>し、1954年の<strong class=\"source-bold\">ジュネーヴ休戦協定</strong>でも独立が確認された。そして、<strong class=\"source-bold\">シハヌーク【シアヌーク】</strong>は自らを元首・首相とする<strong class=\"source-bold\">王政社会主義</strong>を唱え、ベトナム問題に巻き込まれないように、<strong class=\"source-bold\">国際的には中立政策</strong>をとったんだ。ただ、ベトナム情勢の変化がカンボジアに直接影響して、カンボジアは<ruby>翻弄<rt>ほんろう</rt></ruby>されることになるんだ。</p>\n<p>1970年、シハヌークがソ連を訪問している最中に、アメリカと南ベトナムの支援を受けた<strong class=\"source-bold\">ロン＝ノル</strong>がクーデタで権力を掌握し、ベトナム<ruby>撤退<rt>てったい</rt></ruby>を進める<strong class=\"source-bold\">アメリカ</strong>が、東南アジアでの影響力を保持するために<strong class=\"source-bold\">カンボジアに侵攻</strong>してきた。当然、カンボジアでは米軍と組んだロン＝ノルへの反発が強まったよ。</p>\n<p>そしてベトナム戦争が終結すると、シハヌークが左派勢力（<strong class=\"source-bold\">赤色クメール</strong>）と組んで<strong class=\"source-bold\">ロン＝ノル政権を打倒</strong>し、<strong class=\"source-bold\">民主カンプチア</strong>を立てた。しかし、その後の議会選挙で勢力を拡大した赤色クメールの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポル＝ポト</strong></span>が権力を握り、<strong class=\"source-bold\">中国に接近して農村を基盤とする極端な社会主義政策</strong>を進めた。ポル＝ポト政権のもとで、都市住民や</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "450": "<h2>450</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第24回</strong></span> 戦後のインド・東南アジア</p></blockquote>\n<p>知識人の農村への<strong class=\"source-bold\">強制移住</strong>や、反対派の大量虐殺など、国内は混乱したんだ。</p>\n<p>しかし1978年、今度は中国と対立した<strong class=\"source-bold\">ベトナムがソ連の支援</strong>を受けて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カンボジアに<ruby>侵攻<rt>しんこう</rt></ruby></strong></span>してきた。そして、中国寄りの<strong class=\"source-bold\">ポル＝ポト政権を倒して</strong>ベトナム寄りの<strong class=\"source-bold\">ヘン＝サムリン</strong>政権が成立、国名も<strong class=\"source-bold\">カンボジア人民共和国</strong>とすると、反発した中国がベトナムに侵攻した（<strong class=\"source-bold\"><ruby>中越<rt>ちゅうえつ</rt></ruby>戦争</strong>）。そして、ヘン＝サムリン政権に反発した<strong class=\"source-bold\">ポル＝ポト派のゲリラ戦</strong>によってカンボジアは内戦となり、大量の<strong class=\"source-bold\">カンボジア難民</strong>がタイなどに流入したんだ。</p>\n<p>またラオスでも、1960年代から、右派政権とこれに反発した左派の<strong class=\"source-bold\">ラオス愛国戦線【パテート＝ラーオ】</strong>との間で内戦状態になったんだけど、愛国戦線が勝利して、1975年には社会主義国の<strong class=\"source-bold\">ラオス人民民主共和国</strong>になったよ。</p>\n<h4><strong class=\"source-bold\">〈カンボジアをめぐる対立〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><strong class=\"source-bold\">ソ連</strong></td><td><strong class=\"source-bold\">中ソ対立</strong><span data-source-color=\"gray\" style=\"color:#777777\">↔</span></td><td><strong class=\"source-bold\">中国</strong></td></tr><tr><td><span data-source-color=\"red\" data-source-marker=\"curved-line\" style=\"color:#e52715\">⌒</span></td><td></td><td><span data-source-color=\"pink\" data-source-marker=\"curved-line\" style=\"color:#f0a0a0\">⌒</span></td></tr><tr><td><span data-source-color=\"red\" data-source-marker=\"double-line\" style=\"color:#e52715;border-bottom:3px double #e52715\">╲</span></td><td><span data-source-color=\"gray\" style=\"color:#777777\">↕</span><strong class=\"source-bold\">中越戦争</strong></td><td><span data-source-color=\"black\" data-source-line-style=\"dashed\" style=\"color:#001000;border-bottom:1px dashed #001000\">╲</span><strong class=\"source-bold\">米中接近</strong></td></tr><tr><td><span data-source-border=\"black\" data-source-border-shape=\"circle\" style=\"border:2px solid #001000;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><strong class=\"source-bold\">カンボジア</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">←</span></td><td><span data-source-border=\"red\" data-source-border-shape=\"circle\" style=\"border:2px solid #e52715;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><strong class=\"source-bold\">ベトナム</strong></span></td></tr><tr><td><span data-source-color=\"pink\" style=\"color:#f0a0a0\">↙</span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\">↖</span></td><td><span data-source-border=\"brown\" data-source-border-shape=\"circle\" style=\"border:2px solid #a43725;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><strong class=\"source-bold\">アメリカ</strong></span></td></tr></tbody></table></div>\n<blockquote><p><span data-source-border=\"brown\" data-source-border-style=\"solid\" style=\"border:1px solid #a43725;padding:0 0.2em\"><strong class=\"source-bold\">①米軍、カンボジア侵攻</strong><br><strong class=\"source-bold\">→ロン＝ノル政権</strong></span></p>\n<p><span data-source-border=\"pink\" data-source-border-style=\"solid\" style=\"border:1px solid #f0a0a0;padding:0 0.2em\"><strong class=\"source-bold\">②ポル＝ポト政権（親中国）</strong></span></p>\n<p><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">③ベトナム軍、カンボジア侵攻</strong><br><strong class=\"source-bold\">→ヘン＝サムリン政権</strong></span></p></blockquote>\n<p>※数字は時代順</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 内戦が続くカンボジア……<ruby>冷戦<rt>れいせん</rt></ruby>の終結でやっと停戦が実現した！</strong></span></h4>\n<p>1982年、今度は<strong class=\"source-bold\">ヘン＝サムリン政権に反対</strong>するシハヌーク派、ソン＝サン派（旧ロン＝ノル派）、ポル＝ポト派が連合して、<strong class=\"source-bold\">民主カンボジア連合政府</strong>を立てると（首班はソン＝サン）、<strong class=\"source-bold\">ヘン＝サムリン政権との内戦</strong>はますます激化した。しかし、この事態を終わらせたのは、<strong class=\"source-bold\">ソ連の政策変更と冷戦の終結</strong>なんだよ。ソ連の<strong class=\"source-bold\">ゴルバチョフは「新思考外交」</strong>に基づいてベトナム政策を見直し、1989年に<strong class=\"source-bold\">ベトナム軍のカンボジア撤退</strong>を実現した。そして、内戦を終わらせるために国連が動き出したんだ。</p>\n<p>1991年、<strong class=\"source-bold\">パリ和平協定</strong>が結ばれて、翌年には<strong class=\"source-bold\">国連カンボジア<ruby>暫定<rt>ざんてい</rt></ruby>行政機構</strong> <strong class=\"source-bold\">【<ruby>UNTAC<rt>アンタック</rt></ruby>】</strong>が設立されて、公正な選挙が実施されるまでカンボジアの停戦を監視することになった。1993年には選挙に反対した<strong class=\"source-bold\">ポル＝ポト派を除いた総選挙</strong>の結果、<strong class=\"source-bold\">シハヌークが国王に復位</strong>して<strong class=\"source-bold\">カンボジア王国</strong>になった。そして1998年に<strong class=\"source-bold\">ポル＝ポトが死去</strong>すると、長く続いた<strong class=\"source-bold\">内戦は完全に終わった</strong>んだ。その後、<strong class=\"source-bold\">フンセン</strong>政権が<strong class=\"source-bold\"><ruby>ASEAN<rt>アセアン</rt></ruby>への加盟</strong>を実現するなど、国際社会への復帰と内戦からの<ruby>復興<rt>ふっこう</rt></ruby>が進められているよ。</p>",
  "451": "<h2>451</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の東南アジア</u></p></blockquote>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈ビルマ〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 二度の軍事クーデタ！ 軍事政権下でスー＝チーの民主化運動が続く！</strong></span></h4>\n<p>ビルマでは、独立協定に調印した直後に独立闘争の指導者<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アウン＝サン</strong></span><strong class=\"source-bold\">が暗殺</strong>された！。こりゃ、有力な指導者がいないよ。しかも、1948年に<strong class=\"source-bold\">イギリス連邦から完全独立</strong>して<strong class=\"source-bold\">ビルマ連邦共和国</strong>を立てたものの、<strong class=\"source-bold\">共産党の武装<ruby>蜂起<rt>ほうき</rt></ruby></strong>やカレン族の独立問題などで、国内はずっと不安定なままだ。</p>\n<p>1962年、<strong class=\"source-bold\">軍部クーデタ</strong>で権力を握った<strong class=\"source-bold\">ネ＝ウィン</strong>は“<strong class=\"source-bold\">社会主義化</strong>”を宣言すると、独自の社会主義政策と<ruby>鎖国<rt>さこく</rt></ruby>政策をとり、1980年代後半まで権力を維持していた。しかし、80年代後半に世界的に広がった民主化運動の影響で<strong class=\"source-bold\">ビルマでも民主化運動が拡大</strong>し、ついに政権が崩壊したんだ。</p>\n<p>民主化運動を指導した<strong class=\"source-bold\">アウン＝サンの娘</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アウン＝サン＝スー＝チー</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スー＝チー</strong></span>】</strong>は、1988年に国民民主連盟を結成して支持を広げたよ。しかし、再びビルマでは<strong class=\"source-bold\">軍部クーデタでソウ＝マウン</strong>国防相が実権を握り、民主化運動を武力<ruby>弾圧<rt>だんあつ</rt></ruby>すると、<strong class=\"source-bold\">スー＝チーは自宅<ruby>軟禁<rt>なんきん</rt></ruby></strong>となった。そして、ソウ＝マウンは国家法秩序回復評議会 <strong class=\"source-bold\">【</strong>SLORC<strong class=\"source-bold\">】</strong>を設立すると、国名を<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミャンマー連邦</strong></span>、首都を<strong class=\"source-bold\">ヤンゴン</strong>と改称した。以後、<strong class=\"source-bold\">スー＝チーは軟禁・解放を繰り返され</strong>、1991年には<strong class=\"source-bold\">ノーベル平和賞</strong>を受賞したものの、行動の自由を制限され続けたんだ。しかし、2010年ごろから軍事政権が一定の民主化を認め始め、スー＝チーも軟禁を解かれて政治活動を再開し、2016年には新設の国家顧問に就任して、民主化を進めたんだ。しかし、2021年には<strong class=\"source-bold\">再び軍事クーデタが起きてしまった</strong>。さらに<strong class=\"source-bold\">ロヒンギャ</strong>（ムスリムの少数民族）に対する弾圧も国際的に問題になっているんだ。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈マレーシア・シンガポール〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ マレー人 vs. 中国系住民。マレーシアからシンガポールが独立した！</strong></span></h4>\n<p>続いて<strong class=\"source-bold\">マレーシア</strong>だ。まず、1957年にイギリス連邦内の自治領として<strong class=\"source-bold\">マレー人を中心</strong>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マラヤ連邦</strong></span>が独立し、その後、ラーマン首相によって、マラヤ連邦を中心に、<strong class=\"source-bold\">シンガポール</strong>とボルネオ島（インドネシアではカリマンタン島と呼ぶ）の<strong class=\"source-bold\">サバ・サラワク</strong>をあわせて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マレーシア連邦</strong></span>になった。ただ、人口の過半数に満たない<strong class=\"source-bold\">マレー人優先政策</strong>をとったから、<strong class=\"source-bold\">中国系やインド系の住民が反発</strong>していたんだ。</p>\n<p>そして、1965年には<strong class=\"source-bold\">中国系住民の反発</strong>から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シンガポールが分離・独立</strong></span>したよ。シンガポールは1990年まで<strong class=\"source-bold\">リー＝クアンユー</strong>が首相を務めて<strong class=\"source-bold\">急速な経済発展</strong>を実現し、<strong class=\"source-bold\">アジア<ruby>NIES<rt>ニーズ</rt></ruby>【新興工業経済地域】</strong>の1つに数えられたんだ。シンガポールは、現在でも8割近くが中国系住民だよ。一方のマレーシアも1981年に成立した<strong class=\"source-bold\">マハティール政権</strong>が、日本の経済発展をモデルに<strong class=\"source-bold\">ルック＝イースト政策</strong>を進めたよ。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈フィリピン〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ アメリカからは独立したけど、対米従属が続くフィリピン</strong></span></h4>\n<p>1946年に<strong class=\"source-bold\">フィリピンはアメリカから独立</strong>したけど、独立後もずっとアメリカに従</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "452": "<h2>452</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第24回</strong></span> 戦後のインド・東南アジア</p></blockquote>\n<p>属してたんだ。1951年には<strong class=\"source-bold\"><ruby>米比<rt>べいひ</rt></ruby>相互防衛条約</strong>が結ばれると、アメリカ軍がフィリピンに駐留して、<strong class=\"source-bold\">アメリカ軍の東南アジア政策の拠点</strong>になった。国内では、アメリカに反対する共産党系の<strong class=\"source-bold\">フクバラハップ【フク団】</strong>がゲリラ活動で抵抗したけど、アメリカの支援を受けた政府に<ruby>潰<rt>つぶ</rt></ruby>され続けたんだ。</p>\n<p>そして、ベトナム戦争が始まる1965年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルコス</strong></span>が政権に<ruby>就<rt>つ</rt></ruby>くとアメリカの支援によって、1986年まで続く長期政権になった。マルコス政権下では、<strong class=\"source-bold\">ミンダナオ・スルー諸島</strong>のイスラーム教徒（<strong class=\"source-bold\">モロ民族解放戦線</strong>）による分離独立運動なども起きたけど、<ruby>戒厳令<rt>かいげんれい</rt></ruby>を発して全部武力で制圧した。しかし、長期政権の間に<ruby>腐敗<rt>ふはい</rt></ruby>が進み、政権への不満が高まってきて、マルコスの最大のライバルであった政治家<strong class=\"source-bold\">ベニグノ＝アキノ（父）の暗殺</strong>（1983）をきっかけに、全国で<strong class=\"source-bold\">反政府運動が拡大</strong>したよ。そして、1986年にはベニグノ＝アキノ夫人だった<strong class=\"source-bold\">コラソン＝アキノ</strong>が大衆運動をまとめ、国防軍の支持も受けて大統領になった。ただ、<strong class=\"source-bold\">経済の低迷が続いたから政権は不安定</strong>で、1992年には国防大臣の<strong class=\"source-bold\">ラモス</strong>が大統領になったんだ。</p>\n<p>ラモスは<strong class=\"source-bold\">共産党の合法化</strong>や<strong class=\"source-bold\">モロ民族解放戦線との和平</strong>を実現して国内の安定を図ったけどなかなかうまくいかなかった。こうした低迷から、2010年の大統領選挙では<strong class=\"source-bold\">ベニグノ＝アキノ・コラソン＝アキノ夫妻の息子、ベニグノ＝アキノ（子）</strong>が圧勝したよ。彼は<ruby>貧困<rt>ひんこん</rt></ruby>と不正をなくすと選挙で約束したけど、なかなか成果が上げられなかった。その後、2016年には強烈な反米姿勢をとる<strong class=\"source-bold\">ドゥテルテ</strong>が大統領となり、治安対策やイスラーム教徒居住区への自治権承認などで国内の支持は高かったけど、外交は米中の狭間で揺れまくった感じだね。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈東南アジアの連携〉</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ <ruby>ASEAN<rt>アセアン</rt></ruby>は経済協力機構となる。さらに<ruby>APEC<rt>エイペック</rt></ruby>って何？</strong></span></h4>\n<p>1965年に<strong class=\"source-bold\">アメリカがベトナムへの本格<ruby>介入<rt>かいにゅう</rt></ruby></strong>を始めると、東南アジアでは<strong class=\"source-bold\">アメリカに協力して、北ベトナムを<ruby>封<rt>ふう</rt></ruby>じ込める動き</strong>が加速したよ。まずフィリピンでは親米の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルコス</strong></span>政権が成立して対米従属路線をとり、インドネシアでも<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>九<rt>く</rt></ruby>・<ruby>三〇<rt>さんじゅう</rt></ruby>事件</strong></span>が起きて「<strong class=\"source-bold\">反米・<ruby>容<rt>よう</rt></ruby><ruby>共<rt>きょう</rt></ruby></strong>」の<strong class=\"source-bold\">スカルノが失脚</strong>し、「<strong class=\"source-bold\">親米・反共</strong>」の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スハルト</strong></span>政権ができた。そして、1967年には<strong class=\"source-bold\">インドネシア、マレーシア、シンガポール、フィリピン、タイ</strong>の5カ国で、アメリカのベトナム政策に協力するために<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ASEAN</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東南アジア諸国連合</strong></span>】</strong>が結成されたんだ。これは、ほぼ反共軍事同盟と考えていいよ。</p>\n<blockquote><p>ベトナム戦争の始まった1965年に注目だ！ 東南アジアでは「反共」の動きが強まるよ</p></blockquote>\n<p>ただ、<strong class=\"source-bold\">アメリカがベトナムからの撤退を</strong>打ち出すと、「アメリカのベトナム政策に協力する」という当初の目的は、意味がなくなるよね。「それじゃあ解散？」って思うかもしれないけど、<strong class=\"source-bold\">東南アジア諸国で連携</strong>を続けるなら、ASEANの存在意義もある。こうして1971年には<strong class=\"source-bold\">東南アジア中立化</strong></p>",
  "453": "<h2>453</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の東南アジア</u></p></blockquote>\n<p><strong class=\"source-bold\">を宣言</strong>して、<strong class=\"source-bold\">経済協力機構になった</strong>。さらに、ベトナム戦争終結後の1976年には<strong class=\"source-bold\">東南アジア友好協力条約【バリ条約】</strong>で、幅広く協力することを約束、その後、<strong class=\"source-bold\">ブルネイ、ベトナム、ミャンマー（ビルマ）</strong>、<strong class=\"source-bold\">ラオス、カンボジア</strong>が加盟、1999年には東南アジアのすべての国が加盟する「<strong class=\"source-bold\">ASEAN10</strong>」が実現したんだ。</p>\n<p>その後のASEANでは、さまざまな連携への動きが進められているよ。1992年から進んだ貿易自由化構想から、2015年に<strong class=\"source-bold\">ASEAN経済共同体【AEC】</strong>が発足した。1994年からは、アジア太平洋地域の安全保障を話し合う<strong class=\"source-bold\">ASEAN地域フォーラム</strong>も開かれている。さらに、2000年には<strong class=\"source-bold\">ASEAN諸国に日本・中国・韓国</strong>を加えた「<strong class=\"source-bold\">ASEAN＋3</strong>」による東アジア自由貿易圏、さらには東アジア共同体が提唱されるなど、おもに<strong class=\"source-bold\">経済面での連携を目指した動き</strong>が進んでいるんだ。</p>\n<p>アジア太平洋地域での協力の枠組みはほかにもあるよ。1989年に<strong class=\"source-bold\">オーストラリア首相ホークが提唱</strong>して始まった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">APEC</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アジア太平洋経済協力会議</strong></span>】</strong>は、アジア太平洋地域の経済発展を目的とする<strong class=\"source-bold\">非公式フォーラム</strong>だ（英語名は“Asia-Pacific Economic Cooperation”）。これは正式な国際組織じゃないからメンバーに法的<ruby>拘束力<rt>こうそくりょく</rt></ruby>はなく、とりあえず「毎年集まって話し合おう」ってことだ。最初のメンバーは、日・米・韓・カナダ・オーストラリア・ニュージーランド・当時のASEAN加盟国の計12カ国だったけど、1991年に中国・台湾・<ruby>香港<rt>ホンコン</rt></ruby>（当時は英領）が、その後、メキシコ、チリ、ペルー、ロシア、ベトナム、パプアニューギニアも参加し19カ国・2地域、1993年には<strong class=\"source-bold\">シンガポールに常設事務局も設立</strong>された。</p>\n<p>2018年には、<strong class=\"source-bold\">CPTPP【環太平洋パートナーシップに関する<ruby>包括<rt>ほうかつ</rt></ruby>的及び先進的な協定／TPP11】</strong>も発効した。これはアジアから南北アメリカにまたがる自由貿易圏構想から始まり、2016年に12カ国で調印されたけど（<strong class=\"source-bold\">もともとのTPP</strong>）、<strong class=\"source-bold\">アメリカが離脱</strong>したから、11カ国で発効に至ったよ。さらに2023年には、なんとヨーロッパの国の<strong class=\"source-bold\">イギリスが加盟</strong>することになったんだ。また2020年にはASEANを核として、<strong class=\"source-bold\"><ruby>RCEP<rt>アールセップ</rt></ruby>【地域的な包括的経済連携協定】</strong>も結ばれたけど、<strong class=\"source-bold\">中国と対立するインドが最終段階で離脱</strong>するなど、足並みの乱れもあるんだ。</p>\n<p>今回はこれでおしまい。最後に年号 check！</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\">!!</span> <span data-source-color=\"red\" data-source-background=\"white\" style=\"color:#e52715;background-color:#ffffff\"><strong class=\"source-red-bold\">年号</strong></span><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">のツボ</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">インドシナ戦争<ruby>勃発<rt>ぼっぱつ</rt></ruby></strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1946</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>よ<rt>4</rt></ruby><ruby>無<rt>6</rt></ruby></strong></span>謀な インドシナ）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ジュネーヴ休戦協定</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1954</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>届<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>いつ<rt>5</rt></ruby><ruby>し<rt>4</rt></ruby></strong></span>か 平和の願い）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">第1回アジア・アフリカ会議</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1955</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby></strong></span>ぞ <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>GO<rt>5</rt></ruby><ruby>GO<rt>5</rt></ruby></strong></span> バンドン会議）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>北爆<rt>ほくばく</rt></ruby>開始（ベトナム戦争開戦）</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1965</strong></span>］</td><td>（北爆開始 <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>ひど<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>む<rt>6</rt></ruby><ruby>ご<rt>5</rt></ruby></strong></span>い）</td></tr></tbody></table></div>\n<p>さあ、次回は最後の大物「<strong class=\"source-bold\">中東問題</strong>」だ。これを乗り越えたら、あと一歩だよ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>"
};

